export async function extractPDF(file){const pdfjs=await import('/vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const pdf=await task.promise;try{if(pdf.numPages>250)throw new Error('Document trop long : 250 pages maximum pour cette préparation locale.');const pages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();let text='';for(const item of content.items)if('str'in item)text+=item.str+(item.hasEOL?'\n':' ');pages.push({number:i,text:text.trim()});page.cleanup()}return {text:pages.map(p=>`[Page ${p.number}]\n${p.text}`).join('\n\n'),pages:pdf.numPages,hasText:pages.some(p=>p.text.length>20)}}finally{await pdf.destroy()}}
export async function extractDOCX(file){const buffer=await file.arrayBuffer();const bytes=new Uint8Array(buffer),v=new DataView(buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(v.getUint32(i,true)===0x06054b50){end=i;break}}if(end<0)throw new Error('Fichier DOCX illisible.');let offset=v.getUint32(end+16,true);const count=v.getUint16(end+10,true);for(let i=0;i<count;i++){if(v.getUint32(offset,true)!==0x02014b50)throw new Error('Archive DOCX invalide.');const method=v.getUint16(offset+10,true),size=v.getUint32(offset+20,true),unpacked=v.getUint32(offset+24,true),len=v.getUint16(offset+28,true),extra=v.getUint16(offset+30,true),comment=v.getUint16(offset+32,true),local=v.getUint32(offset+42,true);const name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+len));if(name==='word/document.xml'){if(unpacked>8*1024*1024)throw new Error('Contenu décompressé trop volumineux.');const start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true);let xml;if(method===0)xml=new TextDecoder().decode(bytes.slice(start,start+size));else if(method===8){const reader=new Blob([bytes.slice(start,start+size)]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();const chunks=[];let total=0;while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>8*1024*1024){await reader.cancel();throw new Error('Contenu trop volumineux.')}chunks.push(value)}xml=await new Blob(chunks).text()}else throw new Error('Compression DOCX non prise en charge.');const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw new Error('Le contenu Word est illisible.');return {text:[...doc.getElementsByTagNameNS('*','p')].map(p=>[...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')).join('\n'),pages:null,hasText:true}}offset+=46+len+extra+comment}throw new Error('Texte principal absent du DOCX.')}
